function renderStudioLibrary(){pauseStudioLibrary();const query=$('#studioLibrarySearch').value.toLowerCase(),items=studioLibraryChoices.map(r=>({...r,label:studioLibraryFilter==='asset'?(r.assetLabel||r.label):studioLibraryFilter==='project'?(r.projectLabel||r.label):r.label})).filter(r=>(studioLibraryFilter==='all'||studioLibraryFilter==='project'&&r.projectClip||studioLibraryFilter==='mood'&&r.mood||studioLibraryFilter==='asset'&&r.asset||studioLibraryFilter==='upload'&&r.source!=='generated'||r.source==='generated'&&r.kind===studioLibraryFilter)&&r.label.toLowerCase().includes(query));$('#studioLibraryChoices').innerHTML='<button type="button" id="studioLibraryUpload" class="studio-library-upload"><span>＋</span>파일 업로드<small>이미지 · 영상</small></button>'+items.map(r=>'<article class="studio-library-tile" data-path="'+esc(r.path)+'"><button type="button" class="studio-library-preview" aria-label="'+esc(r.label)+(r.kind==='video'?' 재생·정지':' 선택')+'">'+(r.kind==='video'?'<video src="'+esc(mediaURL(r.path))+'" muted playsinline preload="metadata"></video><span class="studio-library-play">▶</span>':'<img src="'+esc(mediaURL(r.path))+'" alt="'+esc(r.label)+'" loading="lazy">')+'</button><label class="studio-library-check"><input type="checkbox" aria-label="'+esc(r.label)+' 참조 선택"></label><div class="studio-library-caption" title="'+esc(r.label)+'">'+esc(r.label)+'</div></article>').join('');$('#studioLibraryUpload').onclick=()=>$('#studioFiles').click();updateStudioLibrarySelection();for(const video of document.querySelectorAll('#studioLibraryChoices video')){const sync=()=>{video.parentElement.classList.toggle('playing',!video.paused&&!video.ended);video.parentElement.querySelector('.studio-library-play').textContent=video.paused||video.ended?'▶':'Ⅱ';};video.onplay=sync;video.onpause=sync;video.onended=sync;}}
async function loadStudioLibrary(){const projectId=studioLibraryProject;$('#studioLibraryError').textContent='';try{const response=await fetch('/api/project-library?projectId='+encodeURIComponent(projectId)),result=await response.json();if(!response.ok)throw Error(result.error);if(state.projectId!==projectId||studioLibraryProject!==projectId)return;const moods=(state.moodReferences||[]).filter(r=>r.path&&StudioReferences.kind(r)==='image'&&r.kind!=='link');const moodPaths=new Set(moods.map(r=>r.path));studioLibraryChoices=result.items.filter(r=>r.kind!=='audio').map(r=>({...r,mood:moodPaths.has(r.path)}));for(const ref of moods){if(!studioLibraryChoices.some(r=>r.path===ref.path))studioLibraryChoices.push({...ref,label:ref.name||ref.label||'무드보드 이미지',kind:'image',mood:true});else studioLibraryChoices.find(r=>r.path===ref.path).label=ref.name||ref.label||studioLibraryChoices.find(r=>r.path===ref.path).label;}const assetRefs=[];for(const asset of state.assets||[]){if(asset.image)assetRefs.push({path:asset.image,label:asset.name});for(const ref of asset.references||[])if(ref.path)assetRefs.push({...ref,label:asset.name+' · '+(ref.label||'레퍼런스')});}for(const ref of assetRefs){const found=studioLibraryChoices.find(r=>r.path===ref.path);if(found){found.asset=true;found.assetLabel=ref.label;}else studioLibraryChoices.push({...ref,kind:StudioReferences.kind(ref),asset:true});}for(const scene of state.scenes||[])for(const cut of scene.cuts||[])for(const media of [{path:cut.image,kind:'image'},{path:cut.video||cut.videoPath,kind:'video'}]){if(!media.path)continue;const found=studioLibraryChoices.find(r=>r.path===media.path);if(found){found.projectClip=true;found.projectLabel=cut.title;}else studioLibraryChoices.push({...media,label:cut.title,projectLabel:cut.title,projectClip:true});}renderStudioLibrary();}catch(err){if(studioLibraryProject===projectId)$('#studioLibraryError').textContent=err.message;}}
async function openStudioLibrary(){studioLibraryProject=state.projectId;studioLibrarySelected=new Set((studioDraft().references||[]).map(r=>r.path));studioLibraryFilter='all';$('#studioLibrarySearch').value='';document.querySelectorAll('[data-library-filter]').forEach(b=>b.classList.toggle('active',b.dataset.libraryFilter==='all'));$('#studioLibraryChoices').innerHTML='<p class="hint">불러오는 중…</p>';positionStudioLibrary();$('#studioLibraryDialog').showModal();await loadStudioLibrary();}$('#studioLibraryClose').onclick=()=>$('#studioLibraryDialog').close();$('#studioLibraryDialog').addEventListener('close',()=>{pauseStudioLibrary();$('#studioLibraryChoices').replaceChildren();});$('#studioLibrarySearch').oninput=renderStudioLibrary;for(const button of document.querySelectorAll('[data-library-filter]'))button.onclick=()=>{studioLibraryFilter=button.dataset.libraryFilter;document.querySelectorAll('[data-library-filter]').forEach(b=>b.classList.toggle('active',b===button));renderStudioLibrary();};
