const studioSyncBeforeH3Options=studioSyncMode;studioSyncMode=function(){studioSyncBeforeH3Options();syncH3AdvancedAvailability();};$('#studioModel').addEventListener('change',syncH3AdvancedAvailability);$('#studioFamily').addEventListener('change',syncH3AdvancedAvailability);
